<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { Bell, Download, LogOut, Moon, RotateCcw, Ruler, Timer, UserRound } from '@lucide/vue'
import { useAppStore } from '@/stores/app'
const store=useAppStore();const router=useRouter();const saved=ref(false)
function save(){store.profile.weeklyGoal=Math.min(14,Math.max(1,Math.round(store.profile.weeklyGoal)||1));store.profile.name=store.profile.name.trim()||'Athlete';saved.value=true;setTimeout(()=>saved.value=false,1800)}
function logout(){store.logout();router.push('/login')}
function exportData(){const data=JSON.stringify({version:1,exportedAt:new Date().toISOString(),profile:store.profile,routines:store.routineList,exercises:store.exerciseList,workouts:store.history,measurements:store.measurements},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`form-export-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url)}
function reset(){if(window.confirm('Reset all demo data?'))store.resetDemo()}
function changeUnits(event:Event){store.setUnits((event.target as HTMLSelectElement).value as 'kg'|'lb')}
</script>
<template><div class="page narrow-page"><header class="page-head"><div><span class="eyebrow">MAKE IT YOURS</span><h1>Settings</h1><p>Preferences for training and your account.</p></div><button class="btn btn-primary" @click="save">{{ saved?'Saved':'Save changes' }}</button></header><section class="settings-section"><span class="folder-head">PROFILE</span><label class="setting-row"><span class="stat-icon coral"><UserRound :size="19"/></span><span><strong>Display name</strong><small>Shown across your training space</small></span><input v-model="store.profile.name" maxlength="50"/></label><label class="setting-row"><span class="stat-icon coral"><UserRound :size="19"/></span><span><strong>Email</strong><small>Your account address</small></span><input v-model="store.profile.email" type="email"/></label><label class="setting-row"><span class="stat-icon lime"><Ruler :size="19"/></span><span><strong>Weekly goal</strong><small>Target workout frequency</small></span><input v-model.number="store.profile.weeklyGoal" type="number" min="1" max="14"/></label></section><section class="settings-section"><span class="folder-head">TRAINING</span><label class="setting-row"><span class="stat-icon lime"><Ruler :size="19"/></span><span><strong>Weight units</strong><small>Used throughout workouts</small></span><select :value="store.profile.units" @change="changeUnits"><option value="kg">Kilograms</option><option value="lb">Pounds</option></select></label><label class="setting-row"><span class="stat-icon purple"><Timer :size="19"/></span><span><strong>Default rest timer</strong><small>Used for newly added exercises</small></span><select v-model.number="store.profile.defaultRest"><option :value="60">1 minute</option><option :value="90">1 min 30 sec</option><option :value="120">2 minutes</option><option :value="180">3 minutes</option></select></label><button class="setting-row" @click="store.profile.timerAlerts=!store.profile.timerAlerts"><span class="stat-icon amber"><Bell :size="19"/></span><span><strong>Timer alerts</strong><small>Sound and vibration when supported</small></span><span class="toggle" :class="{on:store.profile.timerAlerts}"><i></i></span></button></section><section class="settings-section"><span class="folder-head">APPEARANCE</span><label class="setting-row"><span class="stat-icon purple"><Moon :size="19"/></span><span><strong>Theme</strong><small>Dark is optimized for gym use</small></span><select v-model="store.profile.theme"><option value="dark">Dark</option><option value="light">Light</option></select></label></section><section class="settings-section"><span class="folder-head">YOUR DATA</span><button class="setting-row" @click="exportData"><span class="stat-icon lime"><Download :size="19"/></span><span><strong>Export data</strong><small>Download routines, workouts and measurements</small></span><span>JSON</span></button><button class="setting-row" @click="reset"><span class="stat-icon amber"><RotateCcw :size="19"/></span><span><strong>Reset demo data</strong><small>Restore the original sample content</small></span></button></section><button class="logout-button" @click="logout"><LogOut :size="18"/> Sign out</button></div></template>
